/**
 * 場所の言い方（起点の駅・市区町村）の解決を確かめる駅（本物の `station_catalog()` から写した 34 駅・2026-10-08 B2）。
 *
 * 選んだ理由：
 * - 同じ名前の駅：府中（東京都・徳島県・広島県・京都府）、日本橋（大阪と東京）、大塚（広島と東京）
 * - 同じ名前の区：港区（東京都・名古屋市・大阪市）、中区（横浜市・名古屋市・広島市）、中央区（東京都・大阪市）
 * - 政令市の区：横浜市の 5 区・7 駅（「横浜市」で全区・「港北区」だけでも引ける。神奈川区は「神奈川」＝都道府県の言い方と重なる）
 * - 末尾を補う言い方：「横浜」→ 横浜市（7 駅）と青森県の横浜町（1 駅）、「中央」→ 東京都中央区（5 駅）と山梨県の中央市（1 駅）。
 *   どちらも駅の数が 5 倍以上（中央区はちょうど 5 倍。本物は横浜市 137 駅・中央区 22 駅で、もっと離れている）
 * - 名前に「駅」を含む停留場（富山駅）、「ヶ」の駅（市ヶ谷）
 * - 計画書 §6.1.1 の竹橋・新宿三丁目・立川
 */

import { type CatalogStation } from '@/db/queries'

function s(
  grp: string,
  name: string,
  label: string,
  prefecture: string,
  municipality: string | null,
  municipalityCode: string | null,
  lon: number,
  lat: number,
  paxLatest: number | null,
): CatalogStation {
  return { grp, name, label, prefecture, municipality, municipalityCode, lon, lat, paxLatest }
}

